package main

import "fmt"

// makeCounter mengembalikan closure counter
func makeCounter() func() int {
	count := 0
	return func() int {
		count++
		return count
	}
}

// makeAdder mengembalikan closure adder yang dikonfigurasi
func makeAdder(x int) func(int) int {
	return func(y int) int {
		return x + y
	}
}

// makeMultiplier mengembalikan closure untuk perkalian
func makeMultiplier(factor int) func(int) int {
	return func(n int) int {
		return n * factor
	}
}

func main() {
	// Counter
	c1 := makeCounter()
	c2 := makeCounter()
	fmt.Println("c1:", c1(), c1(), c1()) // 1 2 3
	fmt.Println("c2:", c2(), c2())       // 1 2 (state terpisah)

	// Adder
	add10 := makeAdder(10)
	add100 := makeAdder(100)
	fmt.Println("add10(5):", add10(5))
	fmt.Println("add100(5):", add100(5))

	// Multiplier
	double := makeMultiplier(2)
	triple := makeMultiplier(3)
	fmt.Println("double(7):", double(7))
	fmt.Println("triple(7):", triple(7))
}
